window.AUTH=window.AUTH||{};window.AUTH["18-431"]={"d":"18-431","id":"2018/18-431","n":"United States v. Davis","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2019-02-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-431/88090/20190212154352314_18-431tsUnitedStates.pdf","side":"pet","n":120},{"k":"respondent","label":"Brief of respondents Maurice Lamont Davis, et al.","date":"2019-03-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-431/92179/20190315154445342_2019.03.15%20United%20States%20v.%20Davis%20respondent%20brief%20-%20corrected.pdf","side":"res","n":87},{"k":"reply","label":"Reply of petitioner United States","date":"2019-04-05","url":"https://www.supremecourt.gov/DocketPDF/18/18-431/95476/20190405105710582_18-431rbUnitedStates.pdf","side":"pet","n":78}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-431_7758.pdf","tr":true,"items":[{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"op":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"43","1":"13"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Braverman v. United States","cite":"317 U.S. 49","y":1942,"id":"scdb/1942-022","sc":1,"sum":"1. A conviction upon several counts of an indictment, each charging conspiracy to violate a different penal provision of the Internal Revenue laws, where the jury's verdict is supported by evidence of but a single conspiracy to commit those offenses, will not sustain a sentence of more than two years' imprisonment, the maximum penalty for a single violation of the conspiracy statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Callanan v. United States","cite":"364 U.S. 587","y":1961,"id":"1960/47","sc":1,"op":2,"sum":"Under the Act, obstructing interstate commerce by extortion and conspiring to do so are separate offenses; separate consecutive sentences may be imposed for each offense. Pp. 587-597. 274 F. 2d 601, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"op":4,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Curtis Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Davis v. Michigan Dep’t of the Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"op":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"sum":"The Court held that the term \"cocaine base\" encompasses every form of cocaine that is classified chemically as a base.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"op":3,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"43","2":"9"}},{"t":"case","label":"Dowling v. United States","cite":"493 U.S. 342","y":1990,"id":"1989/88-6025","sc":1,"sum":"Petitioner Dowling was convicted of robbing a Virgin Islands bank while wearing a ski mask and carrying a small pistol. Relying on Federal Rule of Evidence 404(b)-which provides that evidence of other crimes, wrongs, or acts may be admissible against a defendant for purposes other than character evidence-the Government introduced at trial the testimony of one Henry, who stated that a similarly masked and armed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"45","1":"43, 47"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"38, 39, 45","1":"15, 21, 23, 33","2":"13"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"ar":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"45","1":"10, 36"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"passim","1":"1, 37, 45","2":"3, 9, 16"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the federal carjacking law established three separate offenses by the specification of elements, each of which must be charged by indictment, proved beyond a reasonable doubt, and submitted to a jury for its verdict.","sumSrc":"Oyez","by":{"0":"48, 49","2":"18"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"op":2,"ar":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":11,"ar":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"32, 38","1":"passim","2":"5, 10"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"op":3,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"0":"40","1":"49","2":"21"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"op":2,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"40","2":"8"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"53","1":"50, 51","2":"21, 22"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"op":7,"ar":3,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"0":"16, 20, 26, 27, 29, 41","1":"19, 20","2":"4"}},{"t":"case","label":"Ovalles v. United States","cite":"905 F.3d 1231","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/1231/","op":8,"by":{"0":"21, 23, 24, 25, 30, 42","2":"18"}},{"t":"case","label":"Park v. INS","cite":"252 F.3d 1018","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/1018/","op":1,"by":{"0":"39"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Schware v. Board of Bar Exam’rs","cite":"353 U.S. 232","y":1957,"id":"1956/92","sc":1,"sum":"On the record in this case, the State of New Mexico deprived petitioner of due process in denying him the opportunity to qualify for the practice of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"passim"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"op":1,"sum":"The Court held that while a guilty plea could qualify as a predicate offense under the ACCA, courts may only look to the following when determining if that plea admitted to generic burglary: the terms of the charging document, the terms of a plea agreement, or a judicial record in which the defendant confirmed the factual basis for the plea (such as conversation between defendant and judge).","sumSrc":"Oyez","by":{"0":"32, 40, 43"}},{"t":"case","label":"Shuti v. Lynch","cite":"828 F.3d 440","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/828/440/","by":{"0":"41"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21, 54"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"sum":"The Court held that a conviction for resisting arrest counts as a violent felony under the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"38, 45"}},{"t":"case","label":"TXO Prod. Corp. v. Alliance Res. Corp.","cite":"509 U.S. 443","y":1993,"id":"1992/92-479","sc":1,"sum":"The judgment is affirmed. 187 W. Va. 457, 419 S. E. 2d 870, affirmed. JUSTICE STEVENS, joined by THE CHIEF JUSTICE and JUSTICE BLACKMUN, concluded in Parts II and III that the punitive damages award did not violate the substantive component of the Due Process Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":6,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 37, 38, 40, 41","1":"23, 25, 32","2":"9"}},{"t":"case","label":"United States v. Amparo","cite":"68 F.3d 1222","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/68/1222/","op":1,"by":{"0":"39","1":"42"}},{"t":"case","label":"United States v. Barrett","cite":"903 F.3d 166","y":2018,"court":"filed Dec. 3","url":"https://www.courtlistener.com/c/F.3d/903/166/","op":5,"by":{"0":"passim"}},{"t":"case","label":"United States v. Benally","cite":"843 F.3d 350","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/843/350/","by":{"0":"39"}},{"t":"case","label":"United States v. Bushey","cite":"617 F. Supp. 292","y":1985,"court":"D. Vt.","url":"https://www.courtlistener.com/c/F.%20Supp./617/292/","sum":"Describing government’s argument that court should consider whether crime, as committed with a firearm, constitutes a crime of violence.","sumSrc":"brief:0","by":{"0":"36","1":"26"}},{"t":"case","label":"United States v. Credit","cite":"95 F.3d 362","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/95/362/","by":{"0":"9"}},{"t":"case","label":"United States v. Cruz","cite":"805 F.2d 1464","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/805/1464/","op":1,"sum":"Noting that the government “asks us to inquire whether the crime, as committed, actually created a substantial risk of harm.”.","sumSrc":"brief:0","by":{"0":"36","1":"26, 31, 44"}},{"t":"case","label":"United States v. Diaz","cite":"778 F.2d 86","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/778/86/","op":1,"by":{"0":"37","1":"27, 31","2":"12"}},{"t":"case","label":"United States v. Douglas","cite":"907 F.3d 1","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/907/1/","op":2,"sum":"Observing that the Court “fashioned and refined the categorical approach both for practical and constitutional reasons that are specific to the consideration of a prior conviction”.","sumSrc":"brief:0","by":{"0":"passim","2":"5, 17"}},{"t":"case","label":"United States v. Eshetu","cite":"898 F.3d 36","y":2018,"court":"D.C. Cir. filed Aug. 31","url":"https://www.courtlistener.com/c/F.3d/898/36/","op":1,"by":{"0":"50"}},{"t":"case","label":"United States v. Gonzalez-Longoria","cite":"831 F.3d 670","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/670/","by":{"0":"9"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"op":7,"ar":6,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"20, 26, 27, 41","1":"11, 19, 20, 44, 45","2":"4"}},{"t":"case","label":"United States v. Higgs","cite":"353 F.3d 281","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/353/281/","by":{"0":"30"}},{"t":"case","label":"United States v. Jenkins","cite":"849 F.3d 390","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/390/","op":2,"by":{"0":"51, 52","1":"39"}},{"t":"case","label":"United States v. Kennedy","cite":"133 F.3d 53","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/133/53/","op":1,"by":{"0":"39"}},{"t":"case","label":"United States v. Mendez","cite":"992 F.2d 1488","y":1993,"url":"https://www.courtlistener.com/c/F.2d/992/1488/","by":{"0":"39"}},{"t":"case","label":"United States v. Moore","cite":"38 F.3d 977","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/38/977/","op":1,"by":{"0":"39"}},{"t":"case","label":"United States v. Parkes","cite":"497 F.3d 220","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/497/220/","sum":"Noting that injury or death “is a natural consequence of a robbery which is premised on the use of overmastering force and violent armed confrontation”.","sumSrc":"brief:0","by":{"0":"54"}},{"t":"case","label":"United States v. Reid","cite":"517 F.2d 953","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/517/953/","by":{"0":"54"}},{"t":"case","label":"United States v. Rodriguez","cite":"581 F.3d 775","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/775/","sum":"Rejecting argument that categorical approach should apply to Section 3592(c)(4).","sumSrc":"brief:0","by":{"0":"30"}},{"t":"case","label":"United States v. Rodriguez-Moreno","cite":"526 U.S. 275","y":1999,"id":"1998/97-1139","sc":1,"sum":"The Court held that \"[v]enue in a prosecution for using or carrying a firearm 'during and in relation to any crime of violence' in violation of section 924(c)(1) is proper in any district where the crime of violence was committed.\" Justice Thomas wrote for the Court that, \"A kidnapping...does not end until the victim is free.","sumSrc":"Oyez","by":{"0":"19, 20","1":"2, 10, 38","2":"2, 22"}},{"t":"case","label":"United States v. Salas","cite":"889 F.3d 681","y":2018,"court":"filed Oct. 3","url":"https://www.courtlistener.com/c/F.3d/889/681/","op":3,"by":{"0":"51","1":"39"}},{"t":"case","label":"United States v. Simms","cite":"2019 WL 311906","y":2019,"court":"4th Cir. Jan. 24","by":{"0":"42, 50"}},{"t":"case","label":"United States v. St. Hubert","cite":"883 F.3d 1319","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/1319/","by":{"0":"41"}},{"t":"case","label":"United States v. Stephens","cite":"964 F.2d 424","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/964/424/","by":{"0":"50"}},{"t":"case","label":"United States v. Taylor","cite":"176 F.3d 331","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/176/331/","by":{"0":"39"}},{"t":"case","label":"United States v. Thomas","cite":"361 F.3d 653","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/361/653/","by":{"0":"38"}},{"t":"case","label":"United States v. Williams","cite":"343 F.3d 423","y":2003,"url":"https://www.courtlistener.com/c/F.3d/343/423/","op":1,"by":{"0":"39"}},{"t":"case","label":"United States ex rel. Attorney Gen. of U.S. v. Delaware & Hudson Co.","cite":"213 U.S. 366","y":1909,"id":"scdb/1908-137","sc":1,"op":1,"sum":"Although a limitation to its operation might be reasonable and thus assuage the radical results of a prohibitory statute, if it is not'.expressed in the-statute-, to engraft such a limitation would be.pure-judicial legislation: IÁ construing the commodities clause of the Hepburn Act the\"suggestion' of the Government to limit its application to commodities while in the'hánds of a carrier or its first vendee, and, as …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"op":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"op":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"32","1":"30, 43","2":"9"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(2)(B)(i)","(e)(2)(B)(ii)","(2012)","(a)","(c)(2012)","(c)(1)(A)","(c)(1)(A)(i)","(c)(1)(A)(ii)","(c)(1)(A)(iii)","(c)(1)(B)(i)","(c)(1)(C)(i)(2012)","(c)(1)(C)(ii)(2012)","(c)(2)","(c)(3)","(c)(3)(A)","(c)(3)(B)","(c)","(c)(1)(D)","(c)(1)(D)(ii)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"28, 28, 28, 1, 7, 37, 37, 37, 37, 37, 37, 37, 37, 37, 37, 37, 37","2":"9, 11, passim, 2, 3, 4, 6, 3, 20, 3, 4, 12, 13, 15, 4, 19, 21, passim"}},{"t":"law","label":"Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/449","by":{"0":"37","1":"27","2":"10"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"9","1":"29"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1224","by":{"0":"34","1":"24, 35"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)"],"stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1951. Interference with commerce by threats or violence","tname":"Crimes and Criminal Procedure","by":{"0":"10","2":"22"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(M)","(a)(43)(M)(i)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"10, 26, 29"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"0":"3, 6, 7"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(b)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":5,"head":"§16. Crime of violence defined","tname":"Crimes and Criminal Procedure","by":{"0":"28, 28","1":"1, 24","2":"11, 12, 15, passim"}},{"t":"usc","label":"18 U.S.C. § 43","url":"https://www.law.cornell.edu/uscode/text/18/43","subs":["(a)(1)","(a)(2)(B)"],"by":{"0":"28, 28"}},{"t":"usc","label":"18 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/18/111","subs":["(a)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 351","url":"https://www.law.cornell.edu/uscode/text/18/351","subs":["(e)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(b)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 670","url":"https://www.law.cornell.edu/uscode/text/18/670","subs":["(b)(2)(A)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/18/844","subs":["(i)"],"stext":{"head":"§844. Penalties","paras":[[0,"(a) Any person who—"],[1,"(1) violates any of subsections (a) through (i) or (l) through (o) of section 842 shall be fined under this title, imprisoned for not more than 10 years, or both; and"],[1,"(2) violates subsection (p)(2) of section 842, shall be fined under this title, imprisoned not more than 20 years, or both."],[0,"(b) Any person who violates any other provision of section 842 of this chapter shall be fined under this title or imprisoned not more than one year, or both."],[0,"(c)(1) Any explosive materials involved or used or intended to be used in any violation of the provisions of this chapter or any other rule or regulation promulgated thereunder or any violation of any criminal law of the United States shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter."],[0,"(2) Notwithstanding paragraph (1), in the case of the seizure of any explosive materials for any offense for which the materials would be subject to forfeiture in which it would be impracticable or unsafe to remove the materials to a place of storage or would be unsafe to store them, the seizing officer may destroy the explosive materials forthwith. Any destruction under this paragraph shall be in the presence of at least 1 credible witness. The seizing officer shall make a report of the seizure and take samples as the Attorney General may by regulation prescribe."],[0,"(3) Within 60 days after any destruction made pursuant to paragraph (2), the owner of (including any person having an interest in) the property so destroyed may make application to the Attorney General for reimbursement of the value of the property. If the claimant establishes to the satisfaction of the Attorney General that—"],[1,"(A) the property has not been used or involved in a violation of law; or"],[1,"(B) any unlawful involvement or use of the property was without the claimant's knowledge, consent, or willful blindness,"],[0,"the Attorney General shall make an allowance to the claimant not exceeding the value of the property destroyed."],[0,"(d) Whoever transports or receives, or attempts to transport or receive, in interstate or foreign commerce any explosive with the knowledge or intent that it will be used to kill, injure, or intimidate any individual or unlawfully to damage or destroy any building, vehicle, or other real or personal property, shall be imprisoned for not more than ten years, or fined under this title, or both; and if personal injury results to any person, including any public safety officer performing duties as a direct or proximate result of conduct prohibited by this subsection, shall be imprisoned for not more than twenty years or fined under this title, or both; and if death results to any person, including any public safety officer performing duties as a direct or proximate result of conduct prohibited by this subsection, shall be subject to imprisonment for any term of years, or to the death penalty or to life imprisonment."],[0,"(e) Whoever, through the use of the mail, telephone, telegraph, or other instrument of interstate or foreign commerce, or in or affecting interstate or foreign commerce, willfully makes any threat, or maliciously conveys false information knowing the same to be false, concerning an attempt or alleged attempt being made, or to be made, to kill, injure, or intimidate any individual or unlawfully to damage or destroy any building, vehicle, or other real or personal property by means of fire or an explosive shall be imprisoned for not more than 10 years or fined under this title, or both."],[0,"(f)(1) Whoever maliciously damages or destroys, or attempts to damage or destroy, by means of fire or an explosive, any building, vehicle, or other personal or real property in whole or in part owned or possessed by, or leased to, the United States, or any department or agency thereof, or any institution or organization receiving Federal financial assistance, shall be imprisoned for not less than 5 years and not more than 20 years, fined under this title, or both."],[0,"(2) Whoever engages in conduct prohibited by this subsection, and as a result of such conduct, directly or proximately causes personal injury or creates a substantial risk of injury to any person, including any public safety officer performing duties, shall be imprisoned for not less than 7 years and not more than 40 years, fined under this title, or both."],[0,"(3) Whoever engages in conduct prohibited by this subsection, and as a result of such conduct directly or proximately causes the death of any person, including any public safety officer performing duties, shall be subject to the death penalty, or imprisoned for not less than 20 years or for life, fined under this title, or both."],[0,"(g)(1) Except as provided in paragraph (2), whoever possesses an explosive in an airport that is subject to the regulatory authority of the Federal Aviation Administration, or in any building in whole or in part owned, possessed, or used by, or leased to, the United States or any department or agency thereof, except with the written consent of the agency, department, or other person responsible for the management of such building or airport, shall be imprisoned for not more than five years, or fined under this title, or both."],[0,"(2) The provisions of this subsection shall not be applicable to—"],[1,"(A) the possession of ammunition (as that term is defined in regulations issued pursuant to this chapter) in an airport that is subject to the regulatory authority of the Federal Aviation Administration if such ammunition is either in checked baggage or in a closed container; or"],[1,"(B) the possession of an explosive in an airport if the packaging and transportation of such explosive is exempt from, or subject to and in accordance with, regulations of the Pipeline and Hazardous Materials Safety Administration for the handling of hazardous materials pursuant to chapter 51 of title 49."],[0,"(h) Whoever—"],[1,"(1) uses fire or an explosive to commit any felony which may be prosecuted in a court of the United States, or"],[1,"(2) carries an explosive during the commission of any felony which may be prosecuted in a court of the United States,"],[0,"including a felony which provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device shall, in addition to the punishment provided for such felony, be sentenced to imprisonment for 10 years. In the case of a second or subsequent conviction under this subsection, such person shall be sentenced to imprisonment for 20 years. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person convicted of a violation of this subsection, nor shall the term of imprisonment imposed under this subsection run concurrently with any other term of imprisonment including that imposed for the felony in which the explosive was used or carried."],[0,"(i) Whoever maliciously damages or destroys, or attempts to damage or destroy, by means of fire or an explosive, any building, vehicle, or other real or personal property used in interstate or foreign commerce or in any activity affecting interstate or foreign commerce shall be imprisoned for not less than 5 years and not more than 20 years, fined under this title, or both; and if personal injury results to any person, including any public safety officer performing duties as a direct or proximate result of conduct prohibited by this subsection, shall be imprisoned for not less than 7 years and not more than 40 years, fined under this title, or both; and if death results to any person, including any public safety officer performing duties as a direct or proximate result of conduct prohibited by this subsection, shall also be subject to imprisonment for any term of years, or to the death penalty or to life imprisonment."],[0,"(j) For the purposes of subsections (d), (e), (f), (g), (h), and (i) of this section and section 842(p), the term \"explosive\" means gunpowders, powders used for blasting, all forms of high explosives, blasting materials, fuzes (other than electric circuit breakers), detonators, and other detonating agents, smokeless powders, other explosive or incendiary devices within the meaning of paragraph (5) of section 232 of this title, and any chemical compounds, mechanical mixture, or device that contains any oxidizing and combustible units, or other ingredients, in such proportions, quantities, or packing that ignition by fire, by friction, by concussion, by percussion, or by detonation of the compound, mixture, or device or any part thereof may cause an explosion."],[0,"(k) A person who steals any explosives materials which are moving as, or are a part of, or which have moved in, interstate or foreign commerce shall be imprisoned for not more than 10 years, fined under this title, or both."],[0,"(l) A person who steals any explosive material from a licensed importer, licensed manufacturer, or licensed dealer, or from any permittee shall be fined under this title, imprisoned not more than 10 years, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/844?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§844. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"31, 51"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(33)(A)"],"by":{"0":"27"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"by":{"0":"1"}},{"t":"usc","label":"18 U.S.C. § 929","url":"https://www.law.cornell.edu/uscode/text/18/929","stext":{"head":"§929. Use of restricted ammunition","paras":[[0,"(a)(1) Whoever, during and in relation to the commission of a crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime which provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which he may be prosecuted in a court of the United States, uses or carries a firearm and is in possession of armor piercing ammunition capable of being fired in that firearm, shall, in addition to the punishment provided for the commission of such crime of violence or drug trafficking crime be sentenced to a term of imprisonment for not less than five years."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(b) Notwithstanding any other provision of law, the court shall not suspend the sentence of any person convicted of a violation of this section, nor place the person on probation, nor shall the terms of imprisonment run concurrently with any other terms of imprisonment, including that imposed for the crime in which the armor piercing ammunition was used or possessed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/929?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§929. Use of restricted ammunition","tname":"Crimes and Criminal Procedure","by":{"0":"37","2":"11"}},{"t":"usc","label":"18 U.S.C. § 1028","url":"https://www.law.cornell.edu/uscode/text/18/1028","subs":["(b)(1)(D)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 1035","url":"https://www.law.cornell.edu/uscode/text/18/1035","subs":["(a)"],"by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/18/1201","subs":["(a)"],"stext":{"head":"§1201. Kidnapping","paras":[[0,"(a) Whoever unlawfully seizes, confines, inveigles, decoys, kidnaps, abducts, or carries away and holds for ransom or reward or otherwise any person, except in the case of a minor by the parent thereof, when—"],[1,"(1) the person is willfully transported in interstate or foreign commerce, regardless of whether the person was alive when transported across a State boundary, or the offender travels in interstate or foreign commerce or uses the mail or any means, facility, or instrumentality of interstate or foreign commerce in committing or in furtherance of the commission of the offense;"],[1,"(2) any such act against the person is done within the special maritime and territorial jurisdiction of the United States;"],[1,"(3) any such act against the person is done within the special aircraft jurisdiction of the United States as defined in section 46501 of title 49;"],[1,"(4) the person is a foreign official, an internationally protected person, or an official guest as those terms are defined in section 1116(b) of this title; or"],[1,"(5) the person is among those officers and employees described in section 1114 of this title and any such act against the person is done while the person is engaged in, or on account of, the performance of official duties,"],[0,"shall be punished by imprisonment for any term of years or for life and, if the death of any person results, shall be punished by death or life imprisonment."],[0,"(b) With respect to subsection (a)(1), above, the failure to release the victim within twenty-four hours after he shall have been unlawfully seized, confined, inveigled, decoyed, kidnapped, abducted, or carried away shall create a rebuttable presumption that such person has been transported in interstate or foreign commerce. Notwithstanding the preceding sentence, the fact that the presumption under this section has not yet taken effect does not preclude a Federal investigation of a possible violation of this section before the 24-hour period has ended."],[0,"(c) If two or more persons conspire to violate this section and one or more of such persons do any overt act to effect the object of the conspiracy, each shall be punished by imprisonment for any term of years or for life."],[0,"(d) Whoever attempts to violate subsection (a) shall be punished by imprisonment for not more than twenty years."],[0,"(e) If the victim of an offense under subsection (a) is an internationally protected person outside the United States, the United States may exercise jurisdiction over the offense if (1) the victim is a representative, officer, employee, or agent of the United States, (2) an offender is a national of the United States, or (3) an offender is afterwards found in the United States. As used in this subsection, the United States includes all areas under the jurisdiction of the United States including any of the places within the provisions of sections 5 and 7 of this title and section 46501(2) of title 49. For purposes of this subsection, the term \"national of the United States\" has the meaning prescribed in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22))."],[0,"(f) In the course of enforcement of subsection (a)(4) and any other sections prohibiting a conspiracy or attempt to violate subsection (a)(4), the Attorney General may request assistance from any Federal, State, or local agency, including the Army, Navy, and Air Force, any statute, rule, or regulation to the contrary notwithstanding."],[0,"(g) Special Rule for Certain Offenses Involving Children.—"],[1,"(1) To whom applicable.—If—"],[2,"(A) the victim of an offense under this section has not attained the age of eighteen years; and"],[2,"(B) the offender—"],[3,"(i) has attained such age; and"],[3,"(ii) is not—"],[4,"(I) a parent;"],[4,"(II) a grandparent;"],[4,"(III) a brother;"],[4,"(IV) a sister;"],[4,"(V) an aunt;"],[4,"(VI) an uncle; or"],[4,"(VII) an individual having legal custody of the victim;"],[1,"the sentence under this section for such offense shall include imprisonment for not less than 20 years."],[1,"[(2) Repealed. Pub. L. 108–21, title I, §104(b), Apr. 30, 2003, 117 Stat. 653.]"],[0,"(h) As used in this section, the term \"parent\" does not include a person whose parental rights with respect to the victim of an offense under this section have been terminated by a final court order."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Kidnapping","tname":"Crimes and Criminal Procedure","by":{"0":"52, 51","2":"6"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 1959","url":"https://www.law.cornell.edu/uscode/text/18/1959","subs":["(a)"],"by":{"0":"52"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"0":"52"}},{"t":"usc","label":"18 U.S.C. § 2114","url":"https://www.law.cornell.edu/uscode/text/18/2114","subs":["(a)"],"by":{"0":"52"}},{"t":"usc","label":"18 U.S.C. § 2118","url":"https://www.law.cornell.edu/uscode/text/18/2118","subs":["(a)","(e)(3)"],"by":{"0":"28, 28"}},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","subs":["(a)(1)(A)"],"by":{"0":"29"}},{"t":"usc","label":"18 U.S.C. § 2423","url":"https://www.law.cornell.edu/uscode/text/18/2423","subs":["(a)"],"by":{"0":"22"}},{"t":"usc","label":"18 U.S.C. § 3592","url":"https://www.law.cornell.edu/uscode/text/18/3592","subs":["(c)(2)","(c)(4)","(c)(6)"],"by":{"0":"30, 30, 29"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"21 U.S.C. § 858","url":"https://www.law.cornell.edu/uscode/text/21/858","stext":{"head":"§858. Endangering human life while illegally manufacturing controlled substance","paras":[[0,"Whoever, while manufacturing a controlled substance in violation of this subchapter, or attempting to do so, or transporting or causing to be transported materials, including chemicals, to do so, creates a substantial risk of harm to human life shall be fined in accordance with title 18 or imprisoned not more than 10 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/858?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§858. Endangering human life while illegally manufacturing controlled substance","tname":"Food and Drugs","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(a)"],"by":{"0":"54"}},{"t":"case","label":"Ashton v. Kentucky","cite":"384 U.S. 195","y":1966,"id":"1965/619","sc":1,"sum":"Petitioner was indicted and convicted for violating the Kentucky common-law crime of criminal libel. The indictment charged \"the offense of criminal libel\" committed \"by publishing a false and malicious publication which tends to degrade or injuie\" three named persons. The trial court charged that \"criminal libel is defined as any writing calculated to create disturbances of the peace, corrupt the public morals, or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50","2":"22"}},{"t":"case","label":"Blount v. Rizzi","cite":"400 U.S. 410","y":1971,"id":"1970/55","sc":1,"sum":"The administrative censorship scheme created by 39 U. S. C. §§ 4006, 4007 appeal from the United States District Court for the Northern District of Georgia. BLOUNT v. RIZZI","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 46"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"op":7,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"6, 11, 14, 36, 47","2":"12"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Dean v. United States","cite":"137 S. Ct. 1170","y":2017,"id":"2016/15-9260","sc":1,"op":1,"sum":"The Court determined that 18 U.S.C. §924(c) does not prevent a sentencing court from using its discretion to consider the other mandatory minimum sentences a defendant might be facing when calculating an overall appropriate sentence.","sumSrc":"Oyez","by":{"1":"27, 39"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Dowling v. United States","cite":"473 U.S. 207","y":1985,"id":"1984/84-589","sc":1,"sum":"Section 2314 does not reach petitioner's conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc., v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"1":"8, 30","2":"12"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"op":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"1":"8, 28"}},{"t":"case","label":"Kolender v. Lawson","cite":"461 U.S. 352","y":1983,"id":"1982/81-1320","sc":1,"op":1,"sum":"The law was unconstitutionally vague because it gave excessive discretion to the police (in the absence of probable cause for an arrest) whether to stop and interrogate a suspect or leave him alone. The majority hinted that the California statute compromised the constitutional right to freedom of movement.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Manhattan Props., Inc. v. Irving Tr. Co.","cite":"291 U.S. 320","y":1934,"id":"scdb/1933-048","sc":1,"sum":"1. The claim of a landlord for future rents based on a covenant to p'ay rent in a lease terminated by reintry on the bankruptcy of the tenant, is not a provable debt under § 63 (a) of the Bankruptcy Act. P. 332. So held in view of the great weight of judicial authority construing that section and similar provisions of earlier Acts, and in view of the legislative history of the subject.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"sum":"The National Motor Vehicle Theft Act, U. S. C., Title 18, § 408, which punishes whoever transports, or causes to be transported, in interstate or foreign commerce a motor vehicle knowing it to have been stolen, and which defines \"motor vehicle\" as including \"an automobile, automobile truck, automobile wagon, motor cycle, or any other self-propelled vehicle not designed for running on rails,\" does not apply to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"136 S. Ct. 1562","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"1":"7, 22"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"1":"52"}},{"t":"case","label":"Rose v. Clark","cite":"478 U.S. 570","y":1986,"id":"1985/84-1974","sc":1,"sum":"Respondent was charged with the murder of two persons arising from the same incident. At his trial in a Tennessee state court he defended on the ground, inter alia, that he was either insane or incapable of forming the requisite intent to kill the victims. The court instructed the jury on both first-degree murder, which requires proof of premeditation and deliberation under Tennessee law, and second-degree murder, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"op":2,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"op":2,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"op":3,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"1":"47, 48"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"op":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Stirone v. United States","cite":"361 U.S. 212","y":1960,"id":"1959/35","sc":1,"sum":"The conviction is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Tex. Dep’t of Hous. & Cmty. Affairs v. In- clusive Cmtys. Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2507/","sc":1,"by":{"1":"24"}},{"t":"case","label":"Page United Bhd. of Carpenters & Joiners of Am. v. United States","cite":"330 U.S. 395","y":1947,"id":"scdb/1946-062","sc":1,"sum":"1: Conspiracies between employers and employees to restrain interstate commerce violate § 1 of the Sherman Act. Allen Bradley Co. v. Local Union No.8,325 U.S. 797. Pp. 400,411.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"United States v. Aragon","cite":"983 F.2d 1306","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/983/1306/","by":{"1":"16, 31"}},{"t":"case","label":"United States v. Armour","cite":"840 F.3d 904","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/840/904/","by":{"1":"38"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"United States v. Butler","cite":"496 F. App’x 158","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/496/158/","op":1,"by":{"1":"29"}},{"t":"case","label":"United States v. Chimurenga","cite":"760 F.2d 400","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/760/400/","by":{"1":"26, 31"}},{"t":"case","label":"United States ex rel. Guarino v. Uhl","cite":"107 F.2d 399","y":1939,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/107/399/","by":{"1":"31"}},{"t":"case","label":"United States v. Gooch","cite":"850 F.3d 285","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/285/","by":{"1":"38"}},{"t":"case","label":"United States v. Headspeth","cite":"852 F.2d 753","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/852/753/","by":{"1":"31"}},{"t":"case","label":"United States v. Jackson","cite":"865 F.3d 946","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/946/","op":1,"by":{"1":"29","2":"17"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"sum":"The Court held that precedent had established that the type of involuntary servitude prohibited by the Thirteenth Amendment is limited to that “enforced by the use or threatened use of physical or legal coercion.” Involuntary servitude had never before been extended to cover labor compelled by the use of psychological coercion.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"United States v. Kundo","cite":"743 F. App’x 201","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/743/201/","by":{"1":"38"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"1":"9, 30"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"op":3,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"1":"44, 48","2":"20"}},{"t":"case","label":"United States v. Martin Linen Supply Co.","cite":"430 U.S. 564","y":1977,"id":"1976/76-120","sc":1,"sum":"The Double Jeopardy Clause bars appellate 'review and retrial following a judgment of acquittal entered under Rule 29 (c).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"United States v. Meyer","cite":"803 F.2d 246","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/803/246/","by":{"1":"26, 31, 34"}},{"t":"case","label":"United States v. Resendiz-Ponce","cite":"549 U.S. 102","y":2007,"id":"2006/05-998","sc":1,"sum":"The Court ruled that Resendiz-Ponce's indictment was not defective at all, and thus it did not reach the question of whether a failure to state each element of the charged crime can ever be harmless error. Justice John Paul Stevens wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"1":"49","2":"22"}},{"t":"case","label":"United States v. Rogers","cite":"371 F.3d 1225","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/1225/","by":{"1":"16"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"1":"6, 14, 44"}},{"t":"case","label":"United States v. Sherbondy","cite":"865 F.2d 996","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/865/996/","by":{"1":"45"}},{"t":"case","label":"United States v. Simms","cite":"914 F.3d 229","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/914/229/","op":8,"by":{"1":"passim","2":"17, 20, 21"}},{"t":"case","label":"United States v. Singleton","cite":"182 F.3d 7","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/182/7/","by":{"1":"15, 35","2":"14"}},{"t":"case","label":"United States v. Smith","cite":"215 F. Supp. 3d 1026","y":2016,"court":"D. Nev.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/215/1026/","by":{"1":"51"}},{"t":"case","label":"Page United States v. Springfield","cite":"829 F.2d 860","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/829/860/","by":{"1":"31","2":"13"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"United States v. Thompson/Ctr. Arms Co.","cite":"504 U.S. 505","y":1992,"id":"1991/91-164","sc":1,"sum":"The judgment is affirmed. 924 F. 2d 1041, affirmed. JUSTICE SOUTER, joined by THE CHIEF JUSTICE and JUSTICE O'CONNOR, concluded that the Contender and conversion kit when packaged together have not been \"made\" into a short-barreled rifle for NFA purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"United States v. Velazquez-Overa","cite":"100 F.3d 418","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/100/418/","by":{"1":"16"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"op":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"19"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"1":"24, 25, 26"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"1":"32"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(a)"],"by":{"1":"41"}},{"t":"usc","label":"16 U.S.C. § 3373","url":"https://www.law.cornell.edu/uscode/text/16/3373","subs":["(d)"],"by":{"1":"41"}},{"t":"usc","label":"18 U.S.C. § 842","url":"https://www.law.cornell.edu/uscode/text/18/842","subs":["(p)"],"by":{"1":"33"}},{"t":"usc","label":"34 U.S.C. § 10596","url":"https://www.law.cornell.edu/uscode/text/34/10596","subs":["(2)(B)"],"by":{"1":"29"}},{"t":"rule","label":"Fed. R. Crim. P. 12","url":"https://www.law.cornell.edu/rules/frcrmp/rule_12","subs":["(b)(1)"],"by":{"1":"42"}},{"t":"rule","label":"Fed. R. Crim. P. 30","url":"https://www.law.cornell.edu/rules/frcrmp/rule_30","subs":["(d)"],"by":{"1":"52"}},{"t":"rule","label":"Fed. R. Evid. 404","url":"https://www.law.cornell.edu/rules/fre/rule_404","by":{"1":"18"}},{"t":"case","label":"Blockburger v. United States","cite":"284 U.S. 299","y":1932,"id":"scdb/1931-120","sc":1,"ar":2,"sum":"1. Two salesof morphine not in or from the original stamped package, the second having been initiated after the first was complete, held separate and distinct offenses under § 1 of the Narcotics Act, although buyer and seller were the same in both cases and but little time elapsed between the end of the one transaction and the beginning of the other.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Brown v. Ohio","cite":"432 U.S. 161","y":1977,"id":"1976/75-6933","sc":1,"op":3,"sum":"The Double Jeopardy Clause of the Fifth Amendment, applied to the States through the Fourteenth, held to bar prosecution and punishment for the crime of stealing an automobile following prosecution and punishment for the lesser included offense of operating the same vehicle without the owner's consent.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"H. J. Inc. v. Northwestern Bell Tel. Co.","cite":"492 U.S. 229","y":1989,"id":"1988/87-1252","sc":1,"sum":"The Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, which is Title IX of the Organized Crime Control Act of 1970 (OCCA), imposes criminal and civil liability upon persons who engage in certain \"prohibited activities,\" each of which is defined to include, as a necessary element, proof of a \"pattern of racketeering activity,\" § 1962. \"Racketeering activity\" means \"any act or threat …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"op":2,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Nash v. United States","cite":"229 U.S. 373","y":1913,"id":"scdb/1912-243","sc":1,"sum":"In ihany instances a'man’s fate depends upon his rightly estimating, that is as the jury subsequently estimates it, some matter of degreej and there is no constitutional difficulty in the way of enforcing the criminal provisions of the Sherman Anti Trust Act on the ground of uncertainty as to the prohibitions.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Northwest Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"op":3,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"ar":1,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Royce v. Hahn","cite":"151 F.3d 116","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/151/116/","by":{"2":"15"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11, 21"}},{"t":"case","label":"Scales v. United States","cite":"367 U.S. 203","y":1961,"id":"1960/1","sc":1,"sum":"Scales was prosecuted and convicted of a felony for his membership in the Communist Party, which advocated the violent overthrow of the government, and was illegal under the Smith Act.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S Ct. 1204","y":2018,"url":"https://www.courtlistener.com/c/S%20Ct./138/1204/","by":{"2":"5, 9, 10, 16, 17, 21"}},{"t":"case","label":"Star Athletica, L.L.C. v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Torres v. Lynch","cite":"136 S. Ct. 1619","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1619/","sc":1,"by":{"2":"6"}},{"t":"case","label":"United States v. Culbert","cite":"435 U.S. 371","y":1978,"id":"1977/77-142","sc":1,"op":2,"sum":"Finding statute clear and refusing to “manufacture ambiguity where none exists”.","sumSrc":"opinion","by":{"2":"19"}},{"t":"case","label":"United States v. Grace","cite":"461 U.S. 171","y":1983,"id":"1982/81-1863","sc":1,"op":2,"sum":"Section 13k, as applied to the public sidewalks surrounding the Court building, is unconstitutional under the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"United States v. Powell","cite":"379 U.S. 48","y":1964,"id":"1964/54","sc":1,"sum":"On the ground that the respondent corporate taxpayer's returns had been examined for certain years and that, absent fraud, the statute of limitations barred assessment of additional deficiencies, respondent the taxpayer's president refused to produce records summoned by the Internal Revenue Service (IRS) unless it disclosed its basis for believing that fraud had been committed. The Government brought an enforcement …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"United States v. Price","cite":"777 F.3d 700","y":2015,"url":"https://www.courtlistener.com/c/F.3d/777/700/","by":{"2":"6"}},{"t":"case","label":"United States v. Shreveport Grain & Elevator Co.","cite":"287 U.S. 77","y":1932,"id":"scdb/1932-027","sc":1,"op":2,"sum":"Finding statute unambiguous and construing it according to “the natural import of its terms”.","sumSrc":"opinion","by":{"2":"19"}},{"t":"case","label":"United States v. Turner","cite":"501 F.3d 59","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/501/59/","by":{"2":"17"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Weeks v. Angelone","cite":"528 U.S. 225","y":2000,"id":"1999/99-5746","sc":1,"sum":"The Court held that the Constitution was not violated by the Virginia trial judge who, during a capital trial's penalty phase, directed the jury's attention to the allegedly ambiguous paragraph of the jury's instruction in response to the jury's question as to mitigating evidence. \"Given that petitioner's jury was adequately instructed, and given that the trial judge responded to the jury's question by directing its attention to the precise paragraph of the constitutionally adequate instruction that answers its inquiry, the question becomes whether the Constitution requires anything more,\" wrote Chief Justice Rehnquist, \"[w]e hold that it does not.\" Writing for the dissenting minority, Justice John Paul Stevens argued that \"[t]he record in this case establishes, not just a 'reasonable likelihood' of jury confusion, but a virtual certainty that the jury did not realize that there were two distinct legal bases for concluding that a death sentence was not 'justified.'\".","sumSrc":"Oyez","by":{"2":"18"}},{"t":"const","label":"Amendment V","clauses":[["double-jeopardy","Double Jeopardy Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"4"}},{"t":"usc","label":"18 U.S.C. § 942","url":"https://www.law.cornell.edu/uscode/text/18/942","subs":["(e)"],"by":{"2":"9"}},{"t":"law","label":"Pub. L. No. 94-473","url":"https://www.govinfo.gov/link/statute/98/1976","by":{"2":"14"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","by":{"2":"14"}},{"t":"usc","label":"18 U.S.C. § 3156","url":"https://www.law.cornell.edu/uscode/text/18/3156","subs":["(a)(4)"],"by":{"2":"14"}},{"t":"usc","label":"18 U.S.C. § 5038","url":"https://www.law.cornell.edu/uscode/text/18/5038","by":{"2":"11"}},{"t":"usc","label":"18 U.S.C. § 119","url":"https://www.law.cornell.edu/uscode/text/18/119","subs":["(a)"],"by":{"2":"15, 15"}},{"t":"usc","label":"18 U.S.C. § 25","url":"https://www.law.cornell.edu/uscode/text/18/25","subs":["(b)"],"by":{"2":"15, 15"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(h)"],"by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 103-222","url":"https://www.govinfo.gov/link/statute/108/1834","by":{"2":"15"}},{"t":"usc","label":"18 U.S.C. § 1591","url":"https://www.law.cornell.edu/uscode/text/18/1591","subs":["(a)"],"by":{"2":"17"}},{"t":"usc","label":"18 U.S.C. § 2281a","url":"https://www.law.cornell.edu/uscode/text/18/2281a","subs":["(a)(1)(A)"],"by":{"2":"6"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(b)(3)"],"by":{"2":"14"}},{"t":"usc","label":"34 U.S.C. § 20911","url":"https://www.law.cornell.edu/uscode/text/34/20911","subs":["(7)(I)"],"by":{"2":"6"}}]};